import React, { useState, useEffect } from 'react';
import axios from 'axios';

function ViewAvailability() {
  const [date, setDate] = useState('');
  const [workspaces, setWorkspaces] = useState([]);

  useEffect(() => {
    if (date) {
      axios.get('/api/workspace/available', { params: { date } })
        .then(response => setWorkspaces(response.data))
        .catch(error => console.error('Error fetching available workspaces:', error));
    }
  }, [date]);

  return (
    <div>
      <h1>Check Workspace Availability</h1>
      <input type="date" value={date} onChange={e => setDate(e.target.value)} />
      <ul>
        {workspaces.map(workspace => (
          <li key={workspace._id}>{workspace.name} - {workspace.location}</li>
        ))}
      </ul>
    </div>
  );
}

export default ViewAvailability;
